import { useRouter } from 'next/router';
import { ArrowLeft } from 'lucide-react';

export default function Custom404() {
  const router = useRouter();

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-[#0f0c29] via-[#302b63] to-[#24243e] p-4">
      <div className="backdrop-blur-md bg-white/10 border border-white/20 rounded-2xl shadow-2xl p-10 max-w-md w-full text-center text-white">
        <h1 className="text-6xl font-extrabold mb-4">404</h1>
        <h2 className="text-2xl font-semibold mb-2">Page Not Found</h2>
        <p className="mb-6 text-sm text-gray-200">
          Sorry, the page you're looking for doesn't exist or has been moved.
        </p>

        <button
          onClick={() => router.push('/')}
          className="bg-white text-black px-4 py-2 rounded-md hover:bg-gray-200 transition flex items-center justify-center gap-2 mx-auto"
        >
          <ArrowLeft className="w-4 h-4" />
          Go Home
        </button>
      </div>
    </div>
  );
}
